def load_dataset(lang: str = "pt"):
    """Devolve a lista de EvaluationSample com as perguntas no idioma pedido ("pt" ou "en")."""
    key = "query" if lang == "pt" else "query_en"
    return [EvaluationSample(query=s[key], relevant_chunks=s["relevant_chunks"]) for s in RAW_DATASET]
